        String value = raw == null ? "" : raw.trim();
        if (value.isEmpty()) {
            return sheets.today(sheetId);
        }
        try {
            return LocalDate.parse(value, DATE);
        } catch (DateTimeParseException e) {
            throw new InvalidPeriodException("The " + which + "-date must be a date (YYYY-MM-DD)");
        }
    }
}
